@staticmethod
def to_torchscript(model, example_inputs, save_path=None, method="trace", optimize=True):
    if method == "trace":
        traced_model = torch.jit.trace(model, example_inputs)
        script_model = torch.jit.script(traced_model)
    else:
        script_model = torch.jit.script(model)

    if optimize:
        script_model = torch.jit.optimize_for_mobile(script_model)

    if save_path:
        torch.jit.save(script_model, save_path)

    return script_model
```

