@staticmethod
def compress_model(model, example_inputs, methods=["quantize", "optimize"]):
    optimized_model = model

    if "quantize" in methods:
        optimized_model = apply_dynamic_quantization(optimized_model)

    if "prune" in methods:
        optimized_model = apply_pruning(optimized_model, amount=0.2)

    if "optimize" in methods:
        scripted_model = torch.jit.trace(optimized_model, example_inputs)
        optimized_model = torch.jit.optimize_for_mobile(scripted_model)

    return optimized_model
